    return out


def hand_points(pos, R, finger=0.04):
    """Sample points of the hand/finger volume in world (approximate box model)."""
    pts = []
    # palm box: x_h +-0.032, y_h +-0.1, z_h 0..0.066
    for xs in (-0.032, 0.032):
        for ys in (-0.1, -0.05, 0, 0.05, 0.1):
